out=Path('output/doc/LifeTracker_4_כולל_תיאור_תחום_הידע.docx');out.parent.mkdir(parents=True,exist_ok=True)
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
with ZipFile(source) as z,ZipFile(out,'w') as target:
 root=etree.fromstring(z.read('word/document.xml'));body=root.find('w:body',ns)
 for i,p in enumerate(doc.paragraphs):
  # Use the source document's existing Normal style id.
  if p.style.name=='Normal':
   ps=p._p.get_or_add_pPr().find(qn('w:pStyle'))
   if ps is not None: p._p.get_or_add_pPr().remove(ps)
  body.insert(i,p._p)
 for entry in z.infolist():
  data=etree.tostring(root,xml_declaration=True,encoding='UTF-8',standalone=True) if entry.filename=='word/document.xml' else z.read(entry.filename)
  target.writestr(entry,data)
print(out.resolve())
